window.STORY_CHAPTERS["c812b16f5c11dba55"]={"id":"c812b16f5c11dba55","lines":[{"uid":"talk.rushin_2008_1_12#originalText","id":"talk.rushin_2008_1_12","speaker":{"cn":"YUNA","ja":"ユナ"},"text":{"cn":"今天的MVP就是你喔！","ja":"今日のMVPはあなた、だよ!"},"kind":"dialogue"},{"uid":"talk.rushin_2004_1_0#originalText","id":"talk.rushin_2004_1_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"愚人节vol.2 ～艾恩葛朗特流 后篇～","en":"April Fools Vol. 2: Aincrad Style Part 1","ja":"エイプリルフールvol.2　〜アインクラッド流 後編〜"},"kind":"caption"},{"uid":"talk.rushin_2004_1_1#originalText","id":"talk.rushin_2004_1_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长！说什么边倒立边战斗才是《艾恩葛朗特流》，根本是在说谎嘛！！","en":"Kirito! Fighting while doing a handstand... Surely that isn't an Aincrad Style move!","ja":"先輩! 逆立ちしながら戦うのが《アインクラッド流》なんて嘘じゃないですか!!"},"kind":"dialogue"},{"uid":"talk.rushin_2004_1_2#originalText","id":"talk.rushin_2004_1_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"唔……嗯……","en":"Hm... Hmm...","ja":"ん……んん……"},"kind":"dialogue"},{"uid":"talk.rushin_2004_1_3#originalText","id":"talk.rushin_2004_1_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"哇！！！","en":"Eek!","ja":"きゃぁっ!!!"},"kind":"dialogue"},{"uid":"talk.rushin_2004_1_4#originalText","id":"talk.rushin_2004_1_4","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"罗、罗妮耶……你没事吧……？","en":"R-Ronie... are you ok...?","ja":"ロ、ロニエ……大丈夫……?"},"kind":"dialogue"},{"uid":"talk.rushin_2004_1_5#originalText","id":"talk.rushin_2004_1_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"倒立什么的……你怎么了……？","en":"You're doing a handstand... what's going on...?","ja":"逆立ちなんてして……どうしたの……?"},"kind":"dialogue"},{"uid":"talk.rushin_2004_1_6#originalText","id":"talk.rushin_2004_1_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"桐人学长说《艾恩葛朗特流》里，有时候会需要倒立挥剑……","en":"Kirito said that he would swing his sword like this whenever he used the Aincrad Style...","ja":"キリト先輩が、《アインクラッド流》では逆立ちで剣を振るうこともあるとおっしゃって……"},"kind":"dialogue"},{"uid":"talk.rushin_2004_1_7#originalText","id":"talk.rushin_2004_1_7","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"……罗妮耶，妳知道今天是什么日子吗……？","en":"...Ronie... do you know what day it is...?","ja":"……ロニエ、今日が何の日か、知ってる……?"},"kind":"dialogue"},{"uid":"talk.rushin_2004_1_8#originalText","id":"talk.rushin_2004_1_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"抱、抱歉……我没想到妳真的会相信……","en":"S-sorry... I didn't think you would believe it...","ja":"ご、ごめん……まさか信じるとは思わなくて……"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_0#originalText","id":"talk.rushin_2004_2_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"愚人节vol.1 ～艾恩葛朗特流 前篇～","en":"April Fools Vol. 1: Aincrad Style Part 2","ja":"エイプリルフールvol.1　〜アインクラッド流 前編〜"},"kind":"caption"},{"uid":"talk.rushin_2004_2_1#originalText","id":"talk.rushin_2004_2_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不可以说谎啦。骗人也没有好处啊。","en":"Don't lie. Nothing good ever comes from deceiving others.","ja":"嘘はダメだよ人を騙しても、いいことなんてないじゃないか"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_2#originalText","id":"talk.rushin_2004_2_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我不是在骗人，是开玩笑啦。用来取悦人的玩笑不算罪过吧？","en":"It's not a lie, it's a joke. I'm just joking to lighten up the mood. That's not a sin, last I checked.","ja":"嘘じゃなくて、冗談人を楽しませる冗談は罪じゃないだろ?"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_3#originalText","id":"talk.rushin_2004_2_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"听好了罗妮耶，《艾恩葛朗特流》需要的是随机应变。","en":"Got that, Ronie? The Aincrad Style can be used for any situation.","ja":"いいかロニエ、《アインクラッド流》は臨機応変"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_4#originalText","id":"talk.rushin_2004_2_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"有时候可能需要一边倒立一边拿着剑，攻击对手防御较弱的脚边。","en":"If you hold onto your sword while doing a handstand, you can target an enemy's vulnerable legs.","ja":"逆立ちしながら剣を持って防御の薄い相手の足元を狙うこともあるんだ"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_5#originalText","id":"talk.rushin_2004_2_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"倒、倒立吗？！","en":"H-handstand?!","ja":"さ、逆立ちですか?!"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_6#originalText","id":"talk.rushin_2004_2_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"对，妳能倒立吗？","en":"Yes. Can you do a handstand?","ja":"ああ逆立ち、できるか?"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_7#originalText","id":"talk.rushin_2004_2_7","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"不、不……","en":"N-no...","ja":"い、いえ……"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_8#originalText","id":"talk.rushin_2004_2_8","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"（我从来都没有倒立过……我能做到吗……）","en":"(I've never done a handstand before... I wonder if I can even do one...)","ja":"（逆立ちなんてやったことない……私にできるかな……）"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_9#originalText","id":"talk.rushin_2004_2_9","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"（不是能不能做到的问题，是要做到！为了要更接近桐人学长！）","en":"(Not that it matters, I need to do one! Anything if means I get even one step closer to Kirito!)","ja":"（できるできないじゃない、やらなきゃ!キリト先輩に一歩でも近づくんだ!）"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_10#originalText","id":"talk.rushin_2004_2_10","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我会练习的！！","en":"I... I'm going to go practice!","ja":"私、練習してきます!!"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_11#originalText","id":"talk.rushin_2004_2_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊，不，等一……走掉了……","en":"Oh, I mean. Please... wai... there she goes...","ja":"あ、いや、ちょっと待っ……行っちゃった……"},"kind":"dialogue"},{"uid":"talk.rushin_2004_2_12#originalText","id":"talk.rushin_2004_2_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不、不是，我只是打算开个玩笑……","en":"S-sorry. I meant to say it as a joke...","ja":"い、いや、冗談のつもりで言ったんだけど……"},"kind":"dialogue"},{"uid":"talk.rushin_2004_3_0#originalText","id":"talk.rushin_2004_3_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"愚人节vol.3 ～肌肉～","en":"April Fools Vol. 3: Muscles","ja":"エイプリルフールvol.3　〜筋肉〜"},"kind":"caption"},{"uid":"talk.rushin_2004_3_1#originalText","id":"talk.rushin_2004_3_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"尤吉欧学长？怎么了？","en":"Eugeo? What happended?","ja":"ユージオ先輩? どうしました?"},"kind":"dialogue"},{"uid":"talk.rushin_2004_3_2#originalText","id":"talk.rushin_2004_3_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"缇洁……","en":"Tiese...","ja":"ティーゼ……"},"kind":"dialogue"},{"uid":"talk.rushin_2004_3_3#originalText","id":"talk.rushin_2004_3_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"妳可以帮我脱衣服吗……？","en":"Could you take my clothes off...?","ja":"服を脱いでくれるかな……?"},"kind":"dialogue"},{"uid":"talk.rushin_2004_3_4#originalText","id":"talk.rushin_2004_3_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……像这种话怎么可能跟女生说……到底要怎样才能好好说明锻炼肌肉的方法呢。","en":"...is something I could never say to a girl... I wonder how I should approach the subject of building muscle","ja":"……なんて女の子には言えないよね……筋肉のつけ方ってどう説明すればいいんだろう"},"kind":"dialogue"},{"uid":"talk.rushin_2004_3_5#originalText","id":"talk.rushin_2004_3_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"没办法像哥鲁哥罗索学长那样呢……","en":"Looks like it won't go so smooth like Golgorosso...","ja":"ゴルゴロッソ先輩のようにはいかないや……"},"kind":"dialogue"},{"uid":"talk.rushin_2004_4_0#originalText","id":"talk.rushin_2004_4_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"愚人节vol.4 ～第3位神明～","en":"April Fools Vol. 4: The 3rd God","ja":"エイプリルフールvol.4　〜3人目の神〜"},"kind":"caption"},{"uid":"talk.rushin_2004_4_1#originalText","id":"talk.rushin_2004_4_1","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"除了我以外，这个世界没有神！","en":"There are no gods in this world. No one besides me!","ja":"この世界には神はいないよ、僕以外にはね!"},"kind":"dialogue"},{"uid":"talk.rushin_2004_4_2#originalText","id":"talk.rushin_2004_4_2","speaker":{},"text":{"cn":"这个世界有3位神明","en":"There are three gods in this world.","ja":"この世界には3人の神がいる"},"kind":"narration"},{"uid":"talk.rushin_2004_4_3#originalText","id":"talk.rushin_2004_4_3","speaker":{},"text":{"cn":"创世神史提西亚","en":"God of Creation Stacia","ja":"創世神ステイシア"},"kind":"narration"},{"uid":"talk.rushin_2004_4_4#originalText","id":"talk.rushin_2004_4_4","speaker":{},"text":{"cn":"太阳神索鲁斯","en":"Sun Goddess Solus","ja":"太陽神ソルス"},"kind":"narration"},{"uid":"talk.rushin_2004_4_5#originalText","id":"talk.rushin_2004_4_5","speaker":{},"text":{"cn":"而第3位是……","en":"And the third is...","ja":"そして3人目は……"},"kind":"narration"},{"uid":"talk.rushin_2004_4_6#originalText","id":"talk.rushin_2004_4_6","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"叫我妖精王奥伯龙陛下吧！！！","en":"Me! Oberon the Fairy King!","ja":"妖精王オベイロン陛下とそう呼べ!!!!"},"kind":"dialogue"},{"uid":"talk.rushin_2004_5_0#originalText","id":"talk.rushin_2004_5_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"愚人节vol.5 ～鞭～","en":"April Fools Vol. 5: Whip","ja":"エイプリルフールvol.5　〜鞭〜"},"kind":"caption"},{"uid":"talk.rushin_2004_5_1#originalText","id":"talk.rushin_2004_5_1","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"虽说一般都会穿着铠甲，但是作为集成骑士，也必须锻炼肉体……","en":"Though I do have armor, an Integrity Knight must also train physically...","ja":"鎧があるとはいえ、整合騎士たるもの、肉体も鍛えねば……"},"kind":"dialogue"},{"uid":"talk.rushin_2004_5_2#originalText","id":"talk.rushin_2004_5_2","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"请用这条鞭鞭打我的身体。","en":"Would you mind striking my body with this whip.","ja":"この鞭で私の体を打ってくれないか"},"kind":"dialogue"},{"uid":"talk.rushin_2004_5_3#originalText","id":"talk.rushin_2004_5_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我、我要断绝师徒关系！！","en":"E-Excommunicate!","ja":"はっ、破門です!!"},"kind":"dialogue"},{"uid":"talk.rushin_2004_5_4#originalText","id":"talk.rushin_2004_5_4","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"吾、吾师！","en":"M-Master!","ja":"し、師よー！"},"kind":"dialogue"},{"uid":"talk.rushin_2005_1_1#originalText","id":"talk.rushin_2005_1_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哟，你听我说。今天有一件很重要的事要告诉你！","en":"Hey, listen up! I have an important announcement for you today.","ja":"よっ、聞いてくれ今日は大事なお知らせがあるんだ!"},"kind":"dialogue"},{"uid":"talk.rushin_2005_1_2#originalText","id":"talk.rushin_2005_1_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"直到今天，我们的故事已经开始了6个月！","en":"Today marks six months since we started our adventure together!","ja":"今日は僕たちの物語が始まってから6ヶ月!"},"kind":"dialogue"},{"uid":"talk.rushin_2005_1_3#originalText","id":"talk.rushin_2005_1_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"全都多亏了有您一直以来的支持。","en":"And it's all thanks to you and your continued support.","ja":"いつも応援してくださるあなたのおかげです"},"kind":"dialogue"},{"uid":"talk.rushin_2005_1_4#originalText","id":"talk.rushin_2005_1_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"真、真的很感谢您。","en":"R-Really. Thank you.","ja":"ほ、本当に感謝しています"},"kind":"dialogue"},{"uid":"talk.rushin_2005_1_5#originalText","id":"talk.rushin_2005_1_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"哈哈，爱丽丝妳太紧张了啦。","en":"Haha! Looks like Alice is too nervous to talk!","ja":"ははっアリス、緊張しすぎだよ"},"kind":"dialogue"},{"uid":"talk.rushin_2005_1_6#originalText","id":"talk.rushin_2005_1_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"所以，为了向大家表达谢意，我们准备了特别活动！！","en":"To show our appreciation to everyone, we prepared an extra special campaign for you!","ja":"そんなわけで、みんなに感謝の気持ちを伝えたくて特別なキャンペーンを用意したんだ!!"},"kind":"dialogue"},{"uid":"talk.rushin_2005_1_7#originalText","id":"talk.rushin_2005_1_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"名为「半周年特别活动！！」","en":"It's called the 6 Month Anniversary Campaign!","ja":"題して「ハーフアニバーサリーキャンペーン!!」"},"kind":"dialogue"},{"uid":"talk.rushin_2005_1_8#originalText","id":"talk.rushin_2005_1_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我、我也有尽力帮忙准备的！","en":"I-I also did my best to prepare!","ja":"わ、私も、精一杯の準備をさせていただきました!"},"kind":"dialogue"},{"uid":"talk.rushin_2005_1_9#originalText","id":"talk.rushin_2005_1_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"就是这样，以后也一起努力吧！","en":"So we're counting on you! Let's continue to give it our all!","ja":"というわけでこれからも一緒に頑張ろうね!"},"kind":"dialogue"},{"uid":"talk.rushin_2005_1_10#originalText","id":"talk.rushin_2005_1_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那么，三、二、一……","en":"Then, on the count of three: One...two...three...","ja":"それじゃ、せーの……"},"kind":"dialogue"},{"uid":"talk.rushin_2005_1_11#originalText","id":"talk.rushin_2005_1_11","speaker":{},"text":{"cn":"今后也请继续支持我们！","en":"Thanks for your support!","ja":"これからも、応援よろしくおねがいします!"},"kind":"narration"},{"uid":"talk.rushin_2008_1_1#originalText","id":"talk.rushin_2008_1_1","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"哟～最近感觉好像没看到你，所以我就来找你了。","en":"Hey there! I haven't seen you around lately, so I came to visit.","ja":"やっほー最近会ってないから顔見に来ちゃった"},"kind":"dialogue"},{"uid":"talk.rushin_2008_1_2#originalText","id":"talk.rushin_2008_1_2","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"虽说是这样，但我今天为大家带来了一个消息！","en":"But not only that. I have an announcement to make!","ja":"というのもあるけど今日はみんなにお知らせがあるの!"},"kind":"dialogue"},{"uid":"talk.rushin_2008_1_3#originalText","id":"talk.rushin_2008_1_3","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"锵～锵！","en":"Ta-da!","ja":"じゃじゃーん!"},"kind":"dialogue"},{"uid":"talk.rushin_2008_1_4#originalText","id":"talk.rushin_2008_1_4","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"附送主画面角色的钻石套组！每人限定购买1次！","en":"It's a Diamond Pack that includes a Home Character! Limited to one per player!","ja":"ホームキャラ付きダイヤパック!お一人様1回限定!"},"kind":"dialogue"},{"uid":"talk.rushin_2008_1_5#originalText","id":"talk.rushin_2008_1_5","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"这样的话，我就每天都能跟大家见面了！","en":"With this, I'll be able to to meet everyone every day!","ja":"これで毎日、みんなと会えるようになるわね!"},"kind":"dialogue"},{"uid":"talk.rushin_2008_1_6#originalText","id":"talk.rushin_2008_1_6","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"此外！！","en":"P - l - u - s!","ja":"さ・ら・に!"},"kind":"dialogue"},{"uid":"talk.rushin_2008_1_7#originalText","id":"talk.rushin_2008_1_7","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"其实这个特别的套组还有其他的种类唷。","en":"There are actually a couple of different types of this special pack.","ja":"実はこの特別なパック他にも種類があるのよ"},"kind":"dialogue"},{"uid":"talk.rushin_2008_1_8#originalText","id":"talk.rushin_2008_1_8","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"有为了心爱的人和黑暗界的未来，独自一人面对暗神贝库达的那个勇敢的莉琵雅！","en":"Standing up to the Dark God Vector alone for those who she loves and the future of the Dark Territory... She's brave, that Lipia.","ja":"愛するヒトと暗黒界の未来のためにひとり暗黒神ベクタに立ち向かったあの健気なリピアや"},"kind":"dialogue"},{"uid":"talk.rushin_2008_1_9#originalText","id":"talk.rushin_2008_1_9","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"还有，和心爱的人经历悠久的时光终于共结连理的美丽副骑士长法那提欧！","en":"And the beautiful Deputy Fanatio was able to finally reunite with the person who she loves.","ja":"愛するヒトと悠久の時を経てようやく結ばれた美しき副騎士長、ファナティオも!"},"kind":"dialogue"},{"uid":"talk.rushin_2008_1_10#originalText","id":"talk.rushin_2008_1_10","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"一定要去看看喔！","en":"Please check it out!","ja":"ぜひチェックしてみてね!"},"kind":"dialogue"},{"uid":"talk.rushin_2008_1_11#originalText","id":"talk.rushin_2008_1_11","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"那么最后就让我留下一句我特别珍藏的台词吧！","en":"And to wrap things up, I'll leave you some words.","ja":"じゃあ最後にひとこととっておきの台詞を残していくわね"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_10#originalText","id":"talk.rushin_2009_bath_10","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"永不止息的洗澡 vol.1『元老长的耳朵是……』","en":"Overflowing Eternal Affection Vol. 1 - The Prime Senator's Ear...","ja":"とめどなくお風呂は溢れ vol.1 『元老長の耳は……』"},"kind":"caption"},{"uid":"talk.rushin_2009_bath_11#originalText","id":"talk.rushin_2009_bath_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"（元老长的耳朵是驴耳朵！）","en":"(The Prime Senator has the ears of a donkey!)","ja":"（元老長の耳はロバの耳!）"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_12#originalText","id":"talk.rushin_2009_bath_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"（元老长的耳朵是……）","en":"(The Prime Senator's ear...)","ja":"（元老長の耳は……）"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_20#originalText","id":"talk.rushin_2009_bath_20","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"永不止息的洗澡 vol.2『遇见骑士长』","en":"Overflowing Eternal Affection Vol. 2 - An Encounter with the Commander","ja":"とめどなくお風呂は溢れ vol.2 『騎士長と遭遇』"},"kind":"caption"},{"uid":"talk.rushin_2009_bath_21#originalText","id":"talk.rushin_2009_bath_21","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"惨了！我忘了今天是男性浴场的日子……！！","en":"Oh no... Today's bath is men-only...!","ja":"しまった今日は男湯の日だった……!!"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_22#originalText","id":"talk.rushin_2009_bath_22","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"（真是的～骑士长别泡这么久啊！）","en":"(Unbelievable! The commander is taking his sweet time with his bath!)","ja":"（も〜騎士長、長湯してんじゃないわよ!）"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_23#originalText","id":"talk.rushin_2009_bath_23","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"（我再泡下去就要晕倒了～！！）","en":"(I need to get a hold of myself!)","ja":"（こっちがのぼせちゃうじゃな〜い!!）"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_30#originalText","id":"talk.rushin_2009_bath_30","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"永不止息的洗澡 vol.3『混浴』","en":"Overflowing Eternal Affection Vol. 3 - Mixed Bath","ja":"とめどなくお風呂は溢れ vol.3 『混浴』"},"kind":"caption"},{"uid":"talk.rushin_2009_bath_31#originalText","id":"talk.rushin_2009_bath_31","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊～还分男性浴场和女性浴场的日子什么的好麻烦喔。","en":"Sigh. Having separate days for male and female bathes is such a nuisance.","ja":"はぁ〜。男湯の日と女湯の日って面倒くさいわよね"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_31_2#originalText","id":"talk.rushin_2009_bath_31_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"之前也不小心弄错过。","en":"I even mixed them up last time.","ja":"こないだ間違えちゃったし"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_32#originalText","id":"talk.rushin_2009_bath_32","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"干脆改成混浴不就好了吗。","en":"So tired of it. I wonder if having a mixed bath would be better...?","ja":"もういっそ混浴にしちゃえばいいんじゃないのかなぁ"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_33#originalText","id":"talk.rushin_2009_bath_33","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"哇啊！！！不行不行！！绝对不行～！！！","en":"Ahhhhh!!! What am I thinking?! No way!!!","ja":"ぎゃあああ!!!ダメっダメっ!! 絶対ダメ〜!!!"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_40#originalText","id":"talk.rushin_2009_bath_40","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"永不止息的洗澡 vol.4『里涅尔的叹息』","en":"Overflowing Eternal Affection Vol. 4 - Linel's Sorrow","ja":"とめどなくお風呂は溢れ vol.4 『リネルの嘆き』"},"kind":"caption"},{"uid":"talk.rushin_2009_bath_41#originalText","id":"talk.rushin_2009_bath_41","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"（呵呵，是看我的身体看到入迷了吗？）","en":"(Hehe... They must be admiring my physique!)","ja":"（ふふ、私の裸に見とれてるのかしら）"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_41_2#originalText","id":"talk.rushin_2009_bath_41_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"（这些孩子也有可爱之处嘛～）","en":"(These girls are cute in their own way!)","ja":"（この子たちにも可愛いところあるじゃな〜い）"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_42#originalText","id":"talk.rushin_2009_bath_42","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"唉……","en":"Ahhh...","ja":"はぁ……"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_43#originalText","id":"talk.rushin_2009_bath_43","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"要是我的身体能变得跟亚多米尼史特蕾达大人一样就好了……","en":"I hope someday, I can have a body like the Lady Administrator.","ja":"アドミニストレータ様みたいなお体になれるといいなあ……"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_44#originalText","id":"talk.rushin_2009_bath_44","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"欸！？我、我呢？变得像我这样不行吗？！","en":"Huh?! What about me?! Is mine not good enough?!","ja":"えっ!? あ、あたしは?!あたしのはダメなの?!"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_50#originalText","id":"talk.rushin_2009_bath_50","speaker":{"cn":"caption","en":"caption"},"text":{"cn":"永不止息的洗澡 vol.5『法那提欧的素颜』","en":"Overflowing Eternal Affection Vol. 5 - Fanatio's Real Face"},"kind":"caption"},{"uid":"talk.rushin_2009_bath_51#originalText","id":"talk.rushin_2009_bath_51","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"说起来，至今为止，好像也没有人看过副骑士长的素颜。","en":"Speaking of which, up until now just about everyone has said that they have never seen Deputy Fanatio's true face."},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_52#originalText","id":"talk.rushin_2009_bath_52","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"啊哈哈，不会吧？！","en":"Unless?! Hahaha."},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_53#originalText","id":"talk.rushin_2009_bath_53","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"不、不会吧……","en":"C-Could it be...?"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_60#originalText","id":"talk.rushin_2009_bath_60","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"永不止息的洗澡 vol.5『露天浴场』","en":"Overflowing Eternal Affection Vol. 5 - The Open-air Bath","ja":"とめどなくお風呂は溢れ vol.5 『露天風呂』"},"kind":"caption"},{"uid":"talk.rushin_2009_bath_61#originalText","id":"talk.rushin_2009_bath_61","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……","en":"......","ja":"……"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_62#originalText","id":"talk.rushin_2009_bath_62","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"唔！！","en":"Eh!","ja":"っ!!"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_63#originalText","id":"talk.rushin_2009_bath_63","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"在这边挥上一击，然后让外面的风吹进来的话这浴场一定会更舒服吧……","en":"If I open up this side, that should let in some wind and make the bath even better...","ja":"そのへんに一撃食らわせたら、外の風が入ってもっと気持ちいいお風呂になるかも……"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_64#originalText","id":"talk.rushin_2009_bath_64","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不过，虽说是窗户，但在这个圣堂墙壁开个洞之类的","en":"Even though there are so many windows in the Cathedral, none are open.","ja":"って、いくら窓とはいえこのカセドラルに穴があくなんて"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_65#originalText","id":"talk.rushin_2009_bath_65","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"是不可能的吧～","en":"I guess I shouldn't...","ja":"そんなわけないかぁ〜"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_70#originalText","id":"talk.rushin_2009_bath_70","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"永不止息的洗澡 vol.6『游泳』","en":"Overflowing Eternal Affection Vol. 6 - Swimming","ja":"とめどなくお風呂は溢れ vol.6 『水泳』"},"kind":"caption"},{"uid":"talk.rushin_2009_bath_71#originalText","id":"talk.rushin_2009_bath_71","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"竟然可以一个人独占这个大到可以游泳的浴场，在这里工作真是太值得了～","en":"Being able to swim around in such a large bath all to myself is such a nice perk.","ja":"こんな泳げるくらい広いお風呂を独り占めできるなんて、役得よねー"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_72#originalText","id":"talk.rushin_2009_bath_72","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯，不过我已经是个大人，我才不会在这里游泳呢。","en":"Then again, I'm not a child so I don't do that anymore, but...","ja":"ま、あたしは大人だから泳がないけど"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_73#originalText","id":"talk.rushin_2009_bath_73","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"（啪沙啪沙啪沙啪沙……）","en":"(Splash, splash, splash...)","ja":"（バシャバシャバシャバシャ……）"},"kind":"caption"},{"uid":"talk.rushin_2009_bath_74#originalText","id":"talk.rushin_2009_bath_74","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"哇！不、不是的，这是……","en":"Eek! N-No, it's not what it looks...","ja":"きゃっ! ち、違うの、これは……"},"kind":"dialogue"},{"uid":"talk.rushin_2009_bath_75#originalText","id":"talk.rushin_2009_bath_75","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"呜呜……","en":"Ohh...","ja":"うぅ……"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_1#originalText","id":"talk.rushin_2011_1st_aniv_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天有一件很重要的事要跟你说！","en":"I have an important announcement for you today!","ja":"今日は大事なお知らせをしにきたわよ!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_2#originalText","id":"talk.rushin_2011_1st_aniv_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们的故事开始到现在已经快要满1年了！","en":"It's been one whole year since we started our adventure together!","ja":"俺たちの物語が始まってからもうすぐ1年!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_3#originalText","id":"talk.rushin_2011_1st_aniv_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"谢谢大家一直以来的支持。","en":"Thank you for your continued support!","ja":"みんな、いつも応援してくれてありがとう"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_4#originalText","id":"talk.rushin_2011_1st_aniv_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"所以，为了向大家表达谢意，我们准备了豪华的特别活动！！","en":"So to show our thanks, we've prepared a special campaign just for you!","ja":"というわけで、感謝の気持ちを込めて豪華なキャンペーンを用意したんだ!!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_5#originalText","id":"talk.rushin_2011_1st_aniv_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"名为「1周年特别活动！！」","en":"It's called,  the 1-Year Anniversary Campaign!","ja":"題して「1st Anniversary キャンペーン!!」"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_6#originalText","id":"talk.rushin_2011_1st_aniv_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"真的超级豪华！！你肯定会大吃一惊～","en":"It's an extra special occasion, so I think you'll like what you find!","ja":"もうすっごく豪華なんだからっ!!きっと驚くわよ〜"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_7#originalText","id":"talk.rushin_2011_1st_aniv_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵，那就稍微介绍一下。","en":"Hehe. I'll show you just a peak!","ja":"ふふ、ちょっとだけ紹介するわね"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_8#originalText","id":"talk.rushin_2011_1st_aniv_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"比如说有新指令《活化链接》登场，","en":"There'll be the brand new Active Link command,","ja":"新コマンド《アクティブリンク》が登場したり"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_9#originalText","id":"talk.rushin_2011_1st_aniv_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"还有「最多110连抽！！免费招募」等等……","en":"and then there's the Free Scout: Up to 110x...","ja":"「最大110連!! 無料スカウト」とか……"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_10#originalText","id":"talk.rushin_2011_1st_aniv_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"在「1周年特别交换商店」里，还有我化身为史提西亚时的插图。","en":"plus, there'll also be an illustration of me as Stacia in the special 1-Year Anniversary Exchange Point!","ja":"「1st Anniversary 特別交換所」ではステイシア姿のわたしのイラストもあるわ"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_11#originalText","id":"talk.rushin_2011_1st_aniv_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"其他很厉害的活动也会接踵而来，记得要注意公告喔！！","en":"Other events will also be packed in together, so make sure to read the Notice for more details!","ja":"他にもすごい催しが目白押しだからお知らせをしっかり読むのよ!!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_12#originalText","id":"talk.rushin_2011_1st_aniv_12","speaker":{"cn":"桐人","ja":"キリト"},"text":{"cn":"那么，三、二、一……","ja":"それじゃ、せーの……"},"kind":"dialogue"},{"uid":"talk.rushin_2011_1st_aniv_13#originalText","id":"talk.rushin_2011_1st_aniv_13","speaker":{"ja":"キリト"},"text":{"ja":"これからも、応援よろしくおねがいします!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_1_0#originalText","id":"talk.rushin_2011_short_novel_1_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"Underworld的日常 vol.1 『过往昔日』","en":"Daily Life In Underworld, vol. 1: Days of Yore","ja":"アンダーワールドの日常 vol.1 『いにしえの日々』"},"kind":"caption"},{"uid":"talk.rushin_2011_short_novel_1_1#originalText","id":"talk.rushin_2011_short_novel_1_1","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"这可真稀奇，司祭大人竟然会来这里。","en":"Your Eminence, it is not often that I see you here.","ja":"珍しいですね、猊下このような場所へ参られるのは"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_1_2#originalText","id":"talk.rushin_2011_short_novel_1_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"我想说偶尔来呼吸一下外头的空气。","en":"I sometimes like to breathe in the outside air.","ja":"たまにはね外の空気を吸おうと思って"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_1_3#originalText","id":"talk.rushin_2011_short_novel_1_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你们在进行训练吗？真有干劲呢。","en":"Are you all training? You seem to be invigorated.","ja":"あなたたちは、訓練?精が出るわね"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_1_4#originalText","id":"talk.rushin_2011_short_novel_1_4","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"为了守护人界的和平，我等集成骑士日求精进！","en":"We Integrity Knights diligently train every day so as to keep peace in the Human Empire!","ja":"我ら整合騎士、人界の平穏を守るため日々精進しております!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_1_5#originalText","id":"talk.rushin_2011_short_novel_1_5","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"话是这么说，目前也只有我们两个人而已。","en":"And by \"we,\" unfortunately, she means just the two of us.","ja":"と言っても、まだオレたちふたりしかおりませんがね"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_1_6#originalText","id":"talk.rushin_2011_short_novel_1_6","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"不久后我就会让人数增加的。那你们继续加油啰。","en":"There will be more of you in time. Now, train hard for me.","ja":"そのうち増やしてあげるわそれじゃ、がんばりなさいな"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_1_7#originalText","id":"talk.rushin_2011_short_novel_1_7","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"是！","en":"Aye!","ja":"はっ!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_2_0#originalText","id":"talk.rushin_2011_short_novel_2_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"Underworld的日常 vol.2 『伊迪丝和爱丽丝的远行』","en":"Daily Life In Underworld, vol. 2: Eydis and Alice's Long Flight","ja":"アンダーワールドの日常 vol.2 『イーディスとアリスの遠乗り』"},"kind":"caption"},{"uid":"talk.rushin_2011_short_novel_2_1#originalText","id":"talk.rushin_2011_short_novel_2_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天天气真好──这种日子飞翔起来一定很舒服呢。","en":"What a lovely day! A flight would feel really good right now.","ja":"今日はいい天気ねーこんな日は、きっと飛んだら気持ちいいわ"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_2_2#originalText","id":"talk.rushin_2011_short_novel_2_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"的确是万里无云的蓝天呢。这般的蓝天真难得。","en":"Indeed, I've never seen such a clear blue sky as this.","ja":"本当に、雲ひとつない青空ですねこんな青空は珍しい"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_2_3#originalText","id":"talk.rushin_2011_short_novel_2_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"欸，要不要来个小远行？天气这么好，龙一定也会开心的。","en":"Wanna take a long flight somewhere? I think the dragons will love it.","ja":"ねえ、ちょっと遠乗りしない?こんな天気なら、きっと竜たちも喜ぶわよ"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_2_4#originalText","id":"talk.rushin_2011_short_novel_2_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"小远行……我跟伊迪丝阁下吗？","en":"A long flight...with you?","ja":"遠乗り……イーディス殿とですか"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_2_5#originalText","id":"talk.rushin_2011_short_novel_2_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"因为妳看嘛！雨缘跟雾舞也都一副心痒痒的样子喔。","en":"Come on, just look! Amayori and Kirimai are itching to go.","ja":"だって、ほら見て!雨縁と霧舞も、うずうずしてるわよ"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_2_6#originalText","id":"talk.rushin_2011_short_novel_2_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"也对，最近的确比较少与牠们一起飞行……","en":"True, they haven't had much time in the air recently.","ja":"そうですね、確かにここ最近はあまり飛んでいませんでしたが"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_2_7#originalText","id":"talk.rushin_2011_short_novel_2_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"太棒了，就这么决定啰！","en":"Yay! So it's decided!","ja":"やった、決まりね!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_2_8#originalText","id":"talk.rushin_2011_short_novel_2_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"伊迪丝阁下，请不要抱住我！","en":"Eydis, please refrain from hugging me!","ja":"イーディス殿、抱きつくのはおやめください!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_3_0#originalText","id":"talk.rushin_2011_short_novel_3_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"Underworld的日常 vol.3 『爱丽丝和艾尔多利耶的训练』","en":"Daily Life In Underworld, vol. 3: Eldrie's Training With Alice","ja":"アンダーワールドの日常 vol.3 『アリスとエルドリエの稽古』"},"kind":"caption"},{"uid":"talk.rushin_2011_short_novel_3_1#originalText","id":"talk.rushin_2011_short_novel_3_1","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我、我认输！","en":"I...I yield!","ja":"ま、参りました!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_3_2#originalText","id":"talk.rushin_2011_short_novel_3_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你进步得非常多，艾尔多利耶。你很努力在锻炼自己吧？","en":"You've improved a lot, Eldrie. Have you been training hard?","ja":"ずいぶんよくなってきましたね、エルドリエかなり鍛錬しているのではないですか?"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_3_3#originalText","id":"talk.rushin_2011_short_novel_3_3","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"您过奖了，但我还远远不及师父您。","en":"I'm honored. But compared to you, I am still far from worthy.","ja":"お褒めにあずかり恐縮ですですが、まだまだ師には遠く及びませぬ"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_3_4#originalText","id":"talk.rushin_2011_short_novel_3_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"别这么说，我的剑术其实也还不够成熟。","en":"Oh, stop. My sword skills are hardly what I'd call perfect.","ja":"やめてください私の剣など、まだ未熟なのですから"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_3_5#originalText","id":"talk.rushin_2011_short_novel_3_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"那么，今天的训练就到此为止吧。","en":"Now, let's end for the day.","ja":"さあ、今日はもう終わりましょう"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_3_6#originalText","id":"talk.rushin_2011_short_novel_3_6","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"已经结束了吗？那么，请问要不要在我的房间一同品尝葡萄酒呢？","en":"Already? Then, would you fancy some wine in my quarters?","ja":"もう終わりですかならば、私の部屋でワインでもいかがでしょうか"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_3_7#originalText","id":"talk.rushin_2011_short_novel_3_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我、我这次就先不用了。","en":"I a-appreciate the offer, but I'll pass, thank you.","ja":"わ、私は今回は遠慮しておきます"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_3_8#originalText","id":"talk.rushin_2011_short_novel_3_8","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"这样啊……还是说您不喜欢葡萄酒？那么，不妨来些点心或一起用餐……","en":"Ah-hah... Do you dislike wine? I could serve a proper meal…","ja":"そうですか……もしや、ワインは苦手ですか?ならば、菓子や食事も……"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_3_9#originalText","id":"talk.rushin_2011_short_novel_3_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不、不用了！我还有事，先失陪了！","en":"N-No, thank you! I have matters to tend to. Excuse me!","ja":"け、結構です!用事があるので、失礼します!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_0#originalText","id":"talk.rushin_2011_short_novel_4_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"Underworld的日常 vol.4 『学院生活』","en":"Daily Life In Underworld, vol. 4: Life at the Academy","ja":"アンダーワールドの日常 vol.4 『学院生活』"},"kind":"caption"},{"uid":"talk.rushin_2011_short_novel_4_1#originalText","id":"talk.rushin_2011_short_novel_4_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呼──稍微休息一下吧。流了好多汗啊。","en":"Phew, wanna take a break? We worked up quite a sweat.","ja":"ふー、一休みするかずいぶんと汗をかいたな"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_2#originalText","id":"talk.rushin_2011_short_novel_4_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"喂，桐人！不要直接在这里脱衣服啦！","en":"Whoa, Kirito! Don't take off your clothes here!","ja":"おい、キリト!こんなところで服脱ごうとするなよ!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_3#originalText","id":"talk.rushin_2011_short_novel_4_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊，对耶。这里已经不是一群卫兵挤在一起生活的地方了。","en":"Woops, almost forgot. We're not at the garrison anymore.","ja":"おっと、そうだったここはもう衛兵詰め所じゃないんだよな"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_4#originalText","id":"talk.rushin_2011_short_novel_4_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"没错，这里也有女孩子在的……真是的，看了都替你捏一把冷汗。","en":"Yes, think of the women in here! It's so taxing being your friend.","ja":"そうだよ、ここには女の子だっているんだから……まったく、見ててハラハラするよ"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_5#originalText","id":"talk.rushin_2011_short_novel_4_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"抱歉、抱歉。不过，就这方面来说，还在卫兵队时方便多了。","en":"Sorry, my bad. But life sure was easier back at the garrison.","ja":"わるい、わるいしかし、衛兵隊の時は、そういう意味では楽だったな"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_6#originalText","id":"talk.rushin_2011_short_novel_4_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"因为清一色都是男性嘛。","en":"Yeah, it was only men.","ja":"見事に男性しかいなかったもんね"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_7#originalText","id":"talk.rushin_2011_short_novel_4_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我还以为学院里肯定也一样，结果女孩子比想像中还多，吓了我一跳呢。","en":"Yeah, I was surprised at how many girls there are at the Academy.","ja":"てっきり、学院もそうだと思ってたんだけどな思った以上に女子が多くてびっくりしたよ"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_8#originalText","id":"talk.rushin_2011_short_novel_4_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"毕竟修剑学院里也有很多贵族儿女嘛。听说很多贵族会把练剑视为一项修养。","en":"Well, there are a lot of nobles here. I've heard that the sword is a way of life for many of them.","ja":"修剣学院には、貴族の人たちも多いからね貴族には、嗜みとして剣を習う人が多いって聞くし"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_9#originalText","id":"talk.rushin_2011_short_novel_4_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"原来如此，如果真是这样，可不能因为对方是贵族就掉以轻心了。","en":"Makes sense. Guess that means we can't underestimate the nobles.","ja":"なるほどな。だとしたら、貴族だからって油断はできないってことだ"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_10#originalText","id":"talk.rushin_2011_short_novel_4_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"掉以轻心？","en":"What do you mean?","ja":"油断?"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_11#originalText","id":"talk.rushin_2011_short_novel_4_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"因为我们的目标是在这当顶尖……不，是名列前茅并参加剑术大会，对吧？","en":"We have to excel here so that we can enter the Sword Tournament.","ja":"だって、俺たちの目的はここでトップ……じゃなくて首席になって、剣術大会に出ることだろう?"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_4_12#originalText","id":"talk.rushin_2011_short_novel_4_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"说得也是……嗯，我也得加油才行。","en":"Yeah... You're right. I'd better train harder, too.","ja":"そうだね……うん僕も頑張らないと"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_5_0#originalText","id":"talk.rushin_2011_short_novel_5_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"Underworld的日常 vol.5 『罗妮耶和桐人的房间扫除』","en":"Daily Life In Underworld, vol. 5: Ronie and Kirito's Room Cleaning","ja":"アンダーワールドの日常 vol.5 『ロニエとキリトの部屋掃除』"},"kind":"caption"},{"uid":"talk.rushin_2011_short_novel_5_1#originalText","id":"talk.rushin_2011_short_novel_5_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"……很好，床铺整理完毕！","en":"Okay... The bed is made!","ja":"……よし、ベッドのお掃除完了!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_5_2#originalText","id":"talk.rushin_2011_short_novel_5_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"地板也打扫完了……啊，窗户！今天就顺便把窗户也擦干净吧！","en":"I've swept the floor and...oh! I'll clean the windows today!","ja":"床掃除は終わったし……あ、窓!今日はこっちもやっちゃおう!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_5_3#originalText","id":"talk.rushin_2011_short_novel_5_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"抱歉，不小心今天也晚归了……","en":"Sorry I was out late again…","ja":"ごめん、今日も遅くなっちゃって……"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_5_4#originalText","id":"talk.rushin_2011_short_novel_5_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"桐人上级修剑士！欢迎您回来！","en":"Elite Disciple Kirito! Welcome back!","ja":"キリト上級修剣士殿!おかえりなさいませ!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_5_5#originalText","id":"talk.rushin_2011_short_novel_5_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"非、非常抱歉，我还没打扫完……","en":"I-I'm sorry I haven't finished cleaning your room yet, sir…","ja":"も、申し訳ありませんまだ清掃が終わっておらず……"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_5_6#originalText","id":"talk.rushin_2011_short_novel_5_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"咦？难道妳连窗户都帮我擦了吗？不用这么费心啦……","en":"Huh? Were you cleaning my windows? You didn't have to bother…","ja":"え、もしかして窓を掃除してくれたのか?そんなのいいのに……"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_5_7#originalText","id":"talk.rushin_2011_short_novel_5_7","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"不会的，因为这也是随侍的工作！","en":"Oh, no, it is my duty to serve!","ja":"いえ、これも傍付きの役目ですから!"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_5_8#originalText","id":"talk.rushin_2011_short_novel_5_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"把那个拿给我吧，我也一起来打扫。","en":"Give me a broom. I'll help you clean.","ja":"貸して俺も一緒に掃除するから"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_5_9#originalText","id":"talk.rushin_2011_short_novel_5_9","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"这、这怎么行！毕竟这是我的……","en":"B-But you mustn't! This is my…","ja":"そ、そんな!これは私の……"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_5_10#originalText","id":"talk.rushin_2011_short_novel_5_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"没关系啦，这是我的房间，照理说该由我自己清理才对。","en":"I insist. This is my room. It should really be me cleaning it.","ja":"いいからここは俺の部屋なんだから、本来俺が掃除すべきなんだ"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_5_11#originalText","id":"talk.rushin_2011_short_novel_5_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们快点打扫完，然后一起吃点心吧。我买了好吃的回来喔。","en":"Let's get this done so we can eat the snacks I bought.","ja":"さっさと終わらせて、おやつ食べようぜお土産買ってきたから"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_6_0#originalText","id":"talk.rushin_2011_short_novel_6_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"Underworld的日常 vol.6 『桐人和尤吉欧的晋级』","en":"Daily Life In Underworld, vol. 6: Kirito's and Eugeo's Promotion","ja":"アンダーワールドの日常 vol.6 『キリトとユージオの進級』"},"kind":"caption"},{"uid":"talk.rushin_2011_short_novel_6_1#originalText","id":"talk.rushin_2011_short_novel_6_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"阿滋利卡老师，这一年来受您关照了。","en":"Ms. Azurica, thank you for your guidance this past year.","ja":"アズリカ先生、1年間お世話になりました"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_6_2#originalText","id":"talk.rushin_2011_short_novel_6_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"谢谢您的照顾。","en":"Yes, thank you.","ja":"お世話になりました"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_6_3#originalText","id":"talk.rushin_2011_short_novel_6_3","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"你们东西都带了吧？","en":"Do you have everything you need?","ja":"忘れ物はありませんか？"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_6_4#originalText","id":"talk.rushin_2011_short_novel_6_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我想应该……都带了。","en":"Yes...I think so.","ja":"大丈夫……だと思います"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_6_5#originalText","id":"talk.rushin_2011_short_novel_6_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"阿滋利卡老师，我真的给您添了很多麻烦。","en":"Thanks again, Ms. Azurica. You taught us so much.","ja":"アズリカ先生には、本当にいろいろとお世話になりました"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_6_6#originalText","id":"talk.rushin_2011_short_novel_6_6","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"……是啊。","en":"Well... Here's one more lesson.","ja":"……そうですね"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_6_7#originalText","id":"talk.rushin_2011_short_novel_6_7","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"你们已经成为上级修剑士，而上级修剑士应当是初等练士的榜样。","en":"You're now elite disciples who'll be role models for the trainees.","ja":"あなた方は、上級修剣士となりました上級修剣士とは、初等練士たちの模範となるべき存在です"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_6_8#originalText","id":"talk.rushin_2011_short_novel_6_8","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"不只是剑术与神圣术，平常更要多加注意己身的行为举止。","en":"You must be examples in your daily lives as well as in your training.","ja":"剣や神聖術だけでなく、これまで以上に普段の生活に注意をするように"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_6_9#originalText","id":"talk.rushin_2011_short_novel_6_9","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"若有任何烦恼，都欢迎来跟我商量。我随时都会在这里。","en":"If you ever falter, tell me. I'll always be here for you.","ja":"困ったことがあったら、なんでも相談しなさい私はいつでもここにいますから"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_6_10#originalText","id":"talk.rushin_2011_short_novel_6_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"谢谢您， 阿滋利卡老师。","en":"Thank you so very much, Ms. Azurica.","ja":"ありがとうございます、アズリカ先生"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_6_11#originalText","id":"talk.rushin_2011_short_novel_6_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"到时就拜托老师您了！","en":"You're a life-saver!","ja":"頼りにしてます！"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_7_0#originalText","id":"talk.rushin_2011_short_novel_7_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"Underworld的日常 vol.7 『索尔缇莉娜学姊的武器解说』","en":"Daily Life In Underworld, vol. 7: Sortiliena's Weapons Lecture","ja":"アンダーワールドの日常 vol.7 『ソルティリーナ先輩による武器解説』"},"kind":"caption"},{"uid":"talk.rushin_2011_short_novel_7_1#originalText","id":"talk.rushin_2011_short_novel_7_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"桐人，我听说你不太擅长学习神圣术是吧。","en":"Kirito, I hear you aren't doing well in the Sacred Arts.","ja":"キリト、お前は神聖術の授業が苦手だそうだな"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_7_2#originalText","id":"talk.rushin_2011_short_novel_7_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"咦……学姊是听谁说的！？八成是尤吉欧那家伙对吧……","en":"Huh? Who told you that?! Oh, I'll bet it was Eugeo.","ja":"えっ……誰からそのことを!?さてはユージオのやつだな……"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_7_3#originalText","id":"talk.rushin_2011_short_novel_7_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我自己也是比较擅长剑术，所以懂你的心情。不过你看看这个。","en":"As someone who prefers the sword, I sympathize. But look.","ja":"私も剣の方が得意だから、気持ちはわかるだがこれを見てみろ"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_7_4#originalText","id":"talk.rushin_2011_short_novel_7_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这本书是……《武器名鉴》吗？","en":"This book...is it a weapons directory?","ja":"この本は……武器名鑑、ですか?"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_7_5#originalText","id":"talk.rushin_2011_short_novel_7_5","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"这里头记载了古今中外的各种武器，其中还包含了很可怕的武器喔。","en":"It contains weapons from all eras and regions. Some are rather grim.","ja":"これには、古今東西さまざまな武器が載っている中には恐ろしいものもあるぞ"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_7_6#originalText","id":"talk.rushin_2011_short_novel_7_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"例如怎么样的武器？","en":"Grim? Like, in what way?","ja":"例えば、どんな武器ですか?"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_7_7#originalText","id":"talk.rushin_2011_short_novel_7_7","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我想想喔……比如毒剑。剑上涂了毒，只留下小伤也能致死。","en":"Like...poisoned swords that can kill with just a minor cut.","ja":"そうだな……例えば毒剣だ剣自体に毒を仕込み、わずかな傷でも死に至らしめる"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_7_8#originalText","id":"talk.rushin_2011_short_novel_7_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那的确是很可怕……","en":"Yeah, that is pretty grim…","ja":"確かに恐ろしいですね……"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_7_9#originalText","id":"talk.rushin_2011_short_novel_7_9","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"这里的学生可能大多不考虑这类武器，但是我……《赛鲁鲁特流》不一样。","en":"Most students here don't pay heed to this kind of thing, but the Serlut Style is different.","ja":"ここの生徒であれば、大半はそんな武器のことなど考えないだろう。だが私は……《セルルト流》は違う"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_7_10#originalText","id":"talk.rushin_2011_short_novel_7_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……我明白了，我的《艾恩葛朗特流》也跟学姊一样，属于实战用的剑术。","en":"I understand. My Aincrad style is focused on what is effective in combat as well.","ja":"……わかりました俺の《アインクラッド流》も、先輩と同じように実戦の剣です"},"kind":"dialogue"},{"uid":"talk.rushin_2011_short_novel_7_11#originalText","id":"talk.rushin_2011_short_novel_7_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今后我会多学习武器的知识，神圣术的部分……也会试着努力的。","en":"I'll keep studying all kinds of weapons and hopefully, Sacred Arts will come.","ja":"これからは、武器のことも勉強して、術の方も何とか……やってみます"},"kind":"dialogue"},{"uid":"talk.rushin_2012_edith_nightwear_1#originalText","id":"talk.rushin_2012_edith_nightwear_1","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"大家好！今天我有件事情想要宣传一下。","en":"Greetings, I have a message for everyone today!","ja":"みなさんこんにちは今日は宣伝したいことがあるの"},"kind":"dialogue"},{"uid":"talk.rushin_2012_edith_nightwear_2#originalText","id":"talk.rushin_2012_edith_nightwear_2","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"姊姊她说要【偶尔来点小性感】，所以买了一套新的睡衣。","en":"Eydis got a new nightdress for her [After Hours] outfit!","ja":"お姉ちゃんが【たまには色っぽく】してみようってことで寝間着を新調したんだ"},"kind":"dialogue"},{"uid":"talk.rushin_2012_edith_nightwear_3#originalText","id":"talk.rushin_2012_edith_nightwear_3","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"听说只有穿着这套衣服时才会说的特别台词有60句以上，而且都附有语音。","en":"She comes with over 60 lines of voiceover dialogue that are unique to this outfit!","ja":"この衣装の時しか言わない特別な台詞も音声付きで60点以上あるんだって"},"kind":"dialogue"},{"uid":"talk.rushin_2012_edith_nightwear_4#originalText","id":"talk.rushin_2012_edith_nightwear_4","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"虽然我不能透露关于台词的内容……","en":"As to what those lines are, I wouldn't want to ruin the fun...","ja":"どんな台詞があるかは私の口からは言えないんだけど……"},"kind":"dialogue"},{"uid":"talk.rushin_2012_edith_nightwear_5#originalText","id":"talk.rushin_2012_edith_nightwear_5","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"不过除此之外，还有着非常漂亮的插图，真希望大家可以摆放出来好好欣赏。","en":"Plus, she also comes with a beautiful illustration that you can decorate with!","ja":"それに、とっても素敵な絵もあるからぜひ飾ってあげてほしいな"},"kind":"dialogue"},{"uid":"talk.rushin_2012_edith_nightwear_6#originalText","id":"talk.rushin_2012_edith_nightwear_6","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我的姊姊竟然可以这么性感身为妹妹的我也吓了一跳！","en":"Even I'm surprised to see this side of my sister!","ja":"あのお姉ちゃんが、こんなに色っぽくなっちゃうなんて妹の私もびっくりしちゃった!"},"kind":"dialogue"},{"uid":"talk.rushin_2012_edith_nightwear_7#originalText","id":"talk.rushin_2012_edith_nightwear_7","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"详细内容请看公告。","en":"If I peaked your interest, check out the notice!","ja":"詳しくはお知らせを見てね"},"kind":"dialogue"},{"uid":"talk.rushin_2012_edith_nightwear_8#originalText","id":"talk.rushin_2012_edith_nightwear_8","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"以后也请多照顾我家姊姊喔！","en":"You better take good care of my sister!","ja":"これからも、お姉ちゃんのことよろしくお願いします!"},"kind":"dialogue"},{"uid":"talk.rushin_2012_silica_christmas_1#originalText","id":"talk.rushin_2012_silica_christmas_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"大家好，我有个消息要带给大家！","en":"Hello everyone! It's time for an announcement!","ja":"みなさんこんにちはお知らせの時間です!"},"kind":"dialogue"},{"uid":"talk.rushin_2012_silica_christmas_2#originalText","id":"talk.rushin_2012_silica_christmas_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我在艾恩葛朗特迎接圣诞的回忆被制作成卡片插图了！","en":"That time we spent Christmas in Aincrad will now be immortalized in a card illustration!","ja":"アインクラッドで迎えたクリスマスの思い出がカードイラストになりました!"},"kind":"dialogue"},{"uid":"talk.rushin_2012_silica_christmas_3#originalText","id":"talk.rushin_2012_silica_christmas_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"当时刚进入12月，街上突然出现一棵大树，平安夜那天更下起雪来，那时候气氛真的很浪漫啊。","en":"When it's December, a giant tree will pop up in the town and it'll start snowing during Christmas Eve. How romantic!","ja":"12月に入ったら突然街に大きなツリーが現れてイブには雪も降ってとってもロマンチックだったんです"},"kind":"dialogue"},{"uid":"talk.rushin_2012_silica_christmas_4#originalText","id":"talk.rushin_2012_silica_christmas_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"这套服装限定的台词一共有6句。","en":"There are six lines that are unique to this outfit.","ja":"この衣装限定の台詞も6つあるんですよ"},"kind":"dialogue"},{"uid":"talk.rushin_2012_silica_christmas_5#originalText","id":"talk.rushin_2012_silica_christmas_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"记得去看看公告喔。","en":"Please check out the notice!","ja":"お知らせをチェックしてくださいね"},"kind":"dialogue"},{"uid":"talk.rushin_2012_silica_christmas_6#originalText","id":"talk.rushin_2012_silica_christmas_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"圣诞快乐！","en":"Merry Christmas!","ja":"メリー・クリスマス!"},"kind":"dialogue"}]};
